                       '(details.get("requestHeaderConfiguration") or '
                       '{}).get("requestHeaderAllowlist", []),\n'
                       '            "created_at": _time(details.get("createdAt")),\n'
                       '            "updated_at": _time(details.get("lastUpdatedAt")),\n'
                       '            "failure_reason": details.get("failureReason"),\n'
