                       '    for summary in summaries:\n'
                       '        details = _get(\n'
                       '            client, "AgentCore gateway target", "get_gateway_target",\n'
                       '            gatewayIdentifier=gateway_id, targetId=summary["targetId"],\n'
                       '        ) or summary\n'
