                       '            "description": details.get("description"),\n'
                       '            "configuration": _target_configuration(config),\n'
                       '            "credential_provider_types": [\n'
                       '                item.get("credentialProviderType")\n'
                       '                for item in '
                       'details.get("credentialProviderConfigurations", [])\n'
                       '            ],\n'
                       '            "last_synchronized_at": '
                       '_time(details.get("lastSynchronizedAt")),\n'
